const fs=require('fs'),zlib=require('zlib');
function decode(f){
  const b=fs.readFileSync(f); let p=8; let w,h,ct,bd,idat=[];
  while(p<b.length){const len=b.readUInt32BE(p);const type=b.toString('ascii',p+4,p+8);const d=b.slice(p+8,p+8+len);
    if(type==='IHDR'){w=d.readUInt32BE(0);h=d.readUInt32BE(4);bd=d[8];ct=d[9];}
    if(type==='IDAT')idat.push(d); if(type==='IEND')break; p+=12+len;}
  const raw=zlib.inflateSync(Buffer.concat(idat));
  const ch=ct===6?4:ct===2?3:ct===4?2:1; const bpp=ch*(bd/8); const stride=w*bpp;
  const out=Buffer.alloc(h*stride); let pos=0;
  for(let y=0;y<h;y++){const ft=raw[pos++];const line=raw.slice(pos,pos+stride);pos+=stride;
    const cur=out.slice(y*stride,(y+1)*stride);const prev=y?out.slice((y-1)*stride,y*stride):Buffer.alloc(stride);
    for(let x=0;x<stride;x++){const a=x>=bpp?cur[x-bpp]:0,bb=prev[x],c=x>=bpp?prev[x-bpp]:0;let v=line[x];
      if(ft===1)v+=a;else if(ft===2)v+=bb;else if(ft===3)v+=(a+bb)>>1;else if(ft===4){const pa=Math.abs(bb-c),pb=Math.abs(a-c),pc=Math.abs(a+bb-2*c);v+= (pa<=pb&&pa<=pc)?a:(pb<=pc?bb:c);}
      cur[x]=v&255;}}
  return {w,h,ch,bpp,stride,out};
}
module.exports=decode;
EOF
